 async function downloadFiscalArchive(archiveId){try{notify('Préparation et vérification de l’archive…');const archive=ui.fiscalArchives.find(row=>row.id===archiveId),bundle=await api().invoke('export-fiscal-archive',{archiveId}),bundleStatus=fiscalArchiveBundleStatus(bundle);if(bundleStatus==='invalid')throw new Error('Le paquet d’archive renvoyé par le serveur est invalide.');saveFiscalArchiveBundle(bundle,archive?.archive_number);notify(bundleStatus==='signed'?'Archive signée, vérifiée et téléchargée.':'Archive vérifiée et téléchargée sans signature KMS.','success');await renderFiscalArchives(state());}catch(error){console.error('[PILOZ téléchargement archive]',{code:error?.code||'',detail:error?.detail||'',message:error?.message||String(error)});notify(archiveMessage(error),'error');}}

 async function accountingData(companyId,force=false){if(!force&&ui.accountingCache&&ui.accountingCacheCompany===companyId)return ui.accountingCache;const tables=['accounting_fiscal_years','accounting_journals','accounting_settings','accounting_account_mappings','accounting_vat_mappings','accounting_financial_accounts','accounting_payment_method_mappings'];const values=await Promise.all(tables.map(table=>api().query(table,`select=*&company_id=eq.${companyId}&order=created_at.asc`)));ui.accountingCache=Object.fromEntries(tables.map((table,index)=>[table,values[index]]));ui.accountingCacheCompany=companyId;return ui.accountingCache;}
 const tabs=[['exercises','Exercices fiscaux'],['journals','Journaux'],['tiers','Tiers'],['deposits','Acomptes'],['sales','Ventes'],['purchases','Achats'],['vat','TVA'],['financial','Comptes financiers']];
 function inputRow(table,row,fields){return`<tr data-table="${table}" data-id="${row.id||''}">${fields.map(([key,label,type='text'])=>`<td data-label="${esc(label)}">${key==='status'?`<select data-field="status">${[['open','Ouvert'],['closing','Clôture en cours'],['closed','Clôturé']].map(([value,text])=>`<option value="${value}" ${row.status===value?'selected':''}>${text}</option>`).join('')}</select>`:`<input data-field="${key}" type="${type}" value="${attr(type==='checkbox'?'':row[key]??'')}" ${type==='checkbox'&&row[key]?'checked':''}>`}</td>`).join('')}</tr>`;}
 function tableBlock(headers,rows,emptyText='Aucune donnée'){return`<div class="modern-table-shell"><table class="modern-table ops-config-table"><thead><tr>${headers.map(value=>`<th>${esc(value)}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}">${esc(emptyText)}</td></tr>`}</tbody></table></div>`;}
 function thirdPartyPanel(settings){const mode=settings.customer_account_mode||'individualized',length=Math.max(1,Math.min(10,Number(settings.auxiliary_length)||10)),example=individualizedCustomerAccount('Dupont Martin');return`<h2>Tiers et comptes clients</h2><p>Le mode par défaut enregistre un compte stable sur chaque fiche client et l’exporte directement dans CompteNum.</p><div class="ops-settings-fields" data-settings="true"><label class="ops-field"><span>Mode de comptabilisation des clients</span><select data-field="customer_account_mode"><option value="individualized" ${mode==='individualized'?'selected':''}>Compte client individualisé dans CompteNum</option><option value="collective_auxiliary" ${mode==='collective_auxiliary'?'selected':''}>Compte collectif avec auxiliaire</option></select></label>${field('Compte collectif fournisseurs','supplier_collective_account',settings.supplier_collective_account||'401000').replace('<input','<input data-field="supplier_collective_account"')}${mode==='collective_auxiliary'?`${field('Compte collectif clients','customer_collective_account',settings.customer_collective_account||'411').replace('<input','<input data-field="customer_collective_account"')}<label class="ops-check"><input data-field="customer_auxiliary_enabled" type="checkbox" ${settings.customer_auxiliary_enabled!==false?'checked':''}><span>Utiliser un identifiant auxiliaire pour les clients</span></label>${field('Nombre maximal de caractères auxiliaires','auxiliary_length',length,'number','min="1" max="10"').replace('<input','<input data-field="auxiliary_length"')}`:''}<label class="ops-check"><input data-field="supplier_auxiliary_enabled" type="checkbox" ${settings.supplier_auxiliary_enabled!==false?'checked':''}><span>Utiliser un identifiant auxiliaire pour les fournisseurs</span></label></div><div class="ops-info-callout"><strong>Mode par défaut demandé</strong><span>« Dupont Martin » devient <code>${esc(example)}</code> dans <code>CompteNum</code>. <code>CompteLib</code> contient le nom réel et les deux colonnes auxiliaires restent vides.</span></div>`;}
 function depositAccountingExample(method,depositAccount,vatSalesAccount,vatSuspenseAccount){const account=depositAccount||'4191',vatSales=vatSalesAccount||'445713',vatSuspense=vatSuspenseAccount||'445803',direct=method==='direct',label=direct?'Méthode de l’imputation directe':'Méthode du compte d’attente',rows=direct?`<tr><td>411DUPONT</td><td>Débit</td><td>1 100,00</td></tr><tr><td>${esc(account)}</td><td>Crédit</td><td>1 000,00</td></tr><tr><td>${esc(vatSales)}</td><td>Crédit</td><td>100,00</td></tr>`:`<tr><td>411DUPONT</td><td>Débit</td><td>1 100,00</td></tr><tr><td>${esc(account)}</td><td>Crédit</td><td>1 100,00</td></tr><tr><td>${esc(vatSuspense)}</td><td>Débit</td><td>100,00</td></tr><tr><td>${esc(vatSales)}</td><td>Crédit</td><td>100,00</td></tr>`;return`<strong>Exemple — ${label} pour un acompte de 1 100,00 € TTC, dont 100,00 € de TVA</strong>${tableBlock(['Compte','Direction','Montant'],rows)}`;}
 function updateDepositExample(){const target=document.getElementById('ops-deposit-accounting-example'),method=document.querySelector('[data-field="deposit_method"]')?.value||'suspense',deposit=document.querySelector('[data-field="deposit_account"]')?.value.trim()||'4191';if(!target)return;target.innerHTML=depositAccountingExample(method,deposit,target.dataset.vatSales,target.dataset.vatSuspense);}
 function accountingPanel(data,tab){const settings=data.accounting_settings[0]||{};
  if(tab==='exercises')return`<div class="ops-section-head"><div><h2>Exercices fiscaux</h2><p>Les périodes ne peuvent pas se chevaucher. La clôture contrôle les écritures avant de verrouiller l’exercice.</p></div>${button('Nouvel exercice',"PilozOps.addAccounting('fiscal')",'btn-o')}</div>${tableBlock(['Nom','Début','Fin','Statut','Actions'],data.accounting_fiscal_years.map(row=>`${inputRow('accounting_fiscal_years',row,[['name','Nom'],['starts_on','Début','date'],['ends_on','Fin','date'],['status','Statut']]).replace('</tr>',`<td data-label="Actions"><div class="actions">${row.next_year_id?'':button('Créer N+1',`PilozOps.createNextFiscal('${row.id}')`,'btn-o')}${row.status==='closed'?status('Clôturé','success'):button('Clôturer',`PilozOps.closeFiscal('${row.id}')`,'btn-o')}</div></td></tr>`)}`).join(''))}`;
  if(tab==='journals'){const rows=data.accounting_journals.map(row=>`<tr data-table="accounting_journals" data-id="${row.id}"><td><input data-field="code" value="${attr(row.code)}"></td><td><input data-field="label" value="${attr(row.label)}"></td><td><select data-field="journal_type">${[['sales','Ventes'],['purchases','Achats'],['bank','Banque'],['cash','Caisse'],['adjustment','Opérations diverses']].map(([key,label])=>`<option value="${key}" ${row.journal_type===key?'selected':''}>${label}</option>`).join('')}</select></td><td><input data-field="display_order" type="number" value="${Number(row.display_order)||0}"></td><td><input data-field="active" type="checkbox" ${row.active!==false?'checked':''}></td></tr>`).join('');return`<div class="ops-section-head"><div><h2>Journaux</h2><p>La position détermine uniquement l’ordre d’affichage des journaux dans les listes ; elle ne change aucune écriture.</p></div>${button('Nouveau journal',"PilozOps.addAccounting('journal')",'btn-o')}</div>${tableBlock(['Code','Libellé','Type','Position d’affichage','Actif'],rows)}`;}
  if(tab==='tiers')return thirdPartyPanel(settings);
  if(tab==='deposits'){const method=settings.deposit_method==='direct'?'direct':'suspense',deposit=settings.deposit_account||'4191',vatMapping=data.accounting_vat_mappings.find(row=>row.active!==false&&Number(row.tax_rate)===20)||{},vatSales=vatMapping.sales_account||'445713',vatSuspense=vatMapping.suspense_account||'445803';return`<h2>Comptabilisation des acomptes</h2><p>Choisissez comment l’acompte est ventilé dans les écritures et les exports comptables.</p><div class="ops-settings-fields" data-settings="true">${field('Compte d’acompte','deposit_account',deposit).replace('<input','<input data-field="deposit_account" oninput="PilozOps.updateDepositExample()"')}<label class="ops-field"><span>Méthode de comptabilisation</span><select data-field="deposit_method" onchange="PilozOps.updateDepositExample()"><option value="suspense" ${method==='suspense'?'selected':''}>Méthode du compte d’attente</option><option value="direct" ${method==='direct'?'selected':''}>Méthode de l’imputation directe</option></select></label><label class="ops-check"><input data-field="deposit_apply_auxiliary" type="checkbox" ${settings.deposit_apply_auxiliary!==false?'checked':''}><span>Appliquer le compte auxiliaire au compte d’acompte</span></label></div><div id="ops-deposit-accounting-example" class="ops-accounting-example" data-vat-sales="${attr(vatSales)}" data-vat-suspense="${attr(vatSuspense)}">${depositAccountingExample(method,deposit,vatSales,vatSuspense)}</div>`;}
  if(tab==='sales'){const mappings=new Map();data.accounting_account_mappings.filter(row=>row.direction==='sale'&&row.scope_type==='item_type'&&row.active!==false).sort((a,b)=>String(a.effective_from||'').localeCompare(String(b.effective_from||''))||String(a.updated_at||'').localeCompare(String(b.updated_at||''))).forEach(row=>mappings.set(row.scope_value,row));const configuredAccounts=itemTypeRows.map(([key,,defaultCode])=>mappings.get(key)?.account_code||defaultCode),salesRows=itemTypeRows.map(([key,label,defaultCode])=>{const row=mappings.get(key);return`<tr data-table="accounting_account_mappings" data-id="${row?.id||''}" data-direction="sale" data-scope-type="item_type" data-scope-value="${attr(key)}"><td><b>${label}</b></td><td><input data-field="account_code" value="${attr(row?.account_code||defaultCode)}" required pattern="[A-Z0-9]{3,20}" maxlength="20" oninput="this.value=this.value.toUpperCase()"></td></tr>`;}).join(''),vatRows=data.accounting_vat_mappings.filter(row=>row.active!==false).sort((a,b)=>Number(a.tax_rate)-Number(b.tax_rate)).map(row=>{const extension=String(row.sale_account_extension||'');const examples=[...new Set(configuredAccounts.map(code=>extension?`${String(code).replace(/\d{3}$/,'')}${extension}`:code))].slice(0,2).join(' / ');return`<tr data-table="accounting_vat_mappings" data-id="${row.id}"><td><b>${vatLabel(row.tax_rate)}</b></td><td><input data-field="sale_account_extension" value="${attr(extension)}"></td><td><code>${esc(examples)}</code></td></tr>`;}).join('');return`<div class="ops-accounting-split"><section><h2>Comptes de vente par type d’élément</h2><p>Une seule écriture est générée par compte. Les remises diminuent les comptes concernés ; les commentaires sont ignorés et les packs sont ventilés par composant.</p>${tableBlock(['Type d’élément','Compte de vente'],salesRows)}</section><section><h2>Ventilation par taux de TVA</h2>${tableBlock(['Taux de TVA','Extension du compte de vente','Exemple selon les comptes configurés'],vatRows)}</section></div>`;}
  if(tab==='purchases'){const rows=data.accounting_account_mappings.filter(row=>row.direction==='purchase');return`<div class="ops-section-head"><div><h2>Comptes d’achat</h2><p>Les comptes sont définis par type, catégorie ou article. La TVA se configure dans l’onglet TVA.</p></div>${button('Ajouter une règle',"PilozOps.addAccounting('purchase')",'btn-o')}</div>${tableBlock(['Portée','Valeur','Compte','Actif'],rows.map(row=>`<tr data-table="accounting_account_mappings" data-id="${row.id}"><td>${esc(row.scope_type==='item_type'?'Type d’élément':row.scope_type==='category'?'Catégorie':row.scope_type==='item'?'Article':'Global')}</td><td>${esc(accountingLabel(row.scope_value))}</td><td><input data-field="account_code" value="${attr(row.account_code)}"></td><td><input data-field="active" type="checkbox" ${row.active!==false?'checked':''}></td></tr>`).join(''))}`;}
  if(tab==='vat')return`<div class="ops-section-head"><div><h2>TVA</h2><p>Tout taux actif ajouté ici devient immédiatement disponible dans les devis et factures.</p></div>${button('Ajouter un taux',"PilozOps.addAccounting('vat')",'btn-o')}</div>${tableBlock(['Taux','TVA sur achats','TVA sur ventes','Compte d’attente','Actif'],data.accounting_vat_mappings.sort((a,b)=>Number(a.tax_rate)-Number(b.tax_rate)).map(row=>`<tr data-table="accounting_vat_mappings" data-id="${row.id}"><td><input data-field="tax_rate" type="number" step="0.001" value="${attr(row.tax_rate)}"></td><td><input data-field="purchase_account" value="${attr(row.purchase_account||'')}"></td><td><input data-field="sales_account" value="${attr(row.sales_account||'')}"></td><td><input data-field="suspense_account" value="${attr(row.suspense_account||'')}"></td><td><input data-field="active" type="checkbox" ${row.active!==false?'checked':''}></td></tr>`).join(''))}`;
  if(tab==='financial'){const financial=data.accounting_financial_accounts.map(row=>`<tr data-table="accounting_financial_accounts" data-id="${row.id}"><td><input data-field="name" value="${attr(row.name)}"></td><td>${esc(accountingLabel(row.account_type))}</td><td><input data-field="account_code" value="${attr(row.account_code)}"></td><td><input data-field="active" type="checkbox" ${row.active!==false?'checked':''}></td></tr>`).join(''),configured=new Map(data.accounting_payment_method_mappings.map(row=>[String(row.payment_method).toLowerCase(),row])),methods=paymentMethodRows.map(([key,label])=>{const row=configured.get(key)||configured.get(key==='cheque'?'check':key);return`<tr data-table="accounting_payment_method_mappings" data-id="${row?.id||''}" data-payment-method="${attr(row?.payment_method||key)}"><td><b>${label}</b></td><td><input data-field="financial_account_code" value="${attr(row?.financial_account_code||'512100')}" required pattern="[A-Z0-9]{3,20}" maxlength="20" oninput="this.value=this.value.toUpperCase()"></td><td><input data-field="account_extension" value="${attr(row?.account_extension||'')}" pattern="[A-Z0-9]{0,20}" maxlength="20" oninput="this.value=this.value.toUpperCase()"></td><td><input data-field="active" type="checkbox" ${row?.active!==false?'checked':''}></td></tr>`;}).join('');return`<div class="ops-section-head"><div><h2>Comptes financiers</h2><p>Banques et caisse utilisées par les écritures de règlement.</p></div>${button('Ajouter un compte',"PilozOps.addAccounting('financial')",'btn-o')}</div>${tableBlock(['Nom','Type','N° de compte comptable','Actif'],financial)}<div class="ops-section-head"><div><h3>Moyens de paiement</h3><p>Chaque moyen reste modifiable. Le compte financier proposé par défaut est 512100.</p></div></div>${tableBlock(['Moyen de paiement','Compte financier','Extension de compte','Actif'],methods)}`;}
  return empty('Rubrique indisponible','Sélectionnez une rubrique comptable.');}
 function settingsPanel(settings,fields,title,description){return`<h2>${esc(title)}</h2><p>${esc(description)}</p><div class="ops-settings-fields" data-settings="true">${fields.map(([key,label,type='text'])=>type==='checkbox'?`<label class="ops-check"><input data-field="${key}" type="checkbox" ${settings[key]?'checked':''}><span>${esc(label)}</span></label>`:field(label,key,settings[key]??'',type,key==='auxiliary_length'?'min="1" max="10"':'').replace('<input','<input data-field="'+key+'"')).join('')}</div>`;}
 async function renderAccountingSettings(s,force=false){const currentPath=path(),requestedTab=currentPath.startsWith('accounting/settings/')?currentPath.split('/').pop():'exercises';if(tabs.some(([key])=>key===requestedTab))ui.accountingTab=requestedTab;loading('Paramétrage comptable','Exercices, journaux, comptes, TVA et règles de ventilation.');try{const data=await accountingData(s.companyId,force);if(!path().startsWith('accounting/settings'))return;document.getElementById('main').innerHTML=header('Paramétrage comptable','Les nouvelles valeurs s’appliquent aux écritures futures. Les exports déjà figés ne sont jamais modifiés.',`${button('Contrôler le paramétrage','PilozOps.controlAccounting()','btn-o')}${button('Enregistrer','PilozOps.saveAccounting()','btn-p')}`)+`<nav class="ops-tabs">${tabs.map(([key,label])=>`<button class="${ui.accountingTab===key?'active':''}" onclick="PilozOps.setAccountingTab('${key}')">${esc(label)}</button>`).join('')}</nav><section class="phase1-card ops-accounting-form">${accountingPanel(data,ui.accountingTab)}</section><div class="ops-sticky-save">${button('Enregistrer les modifications','PilozOps.saveAccounting()','btn-p')}</div>`;}catch(error){fail(error);}}
 function setAccountingTab(tab){if(!tabs.some(([key])=>key===tab))return;ui.accountingTab=tab;app().go(`accounting/settings/${tab}`);}
 async function createNextFiscal(id){try{await api().rpc('create_next_accounting_fiscal_year',{target_fiscal_year_id:id});ui.accountingCache=null;notify('Exercice suivant créé sans chevauchement.','success');renderAccountingSettings(state(),true);}catch(error){fail(error);}}
 async function closeFiscal(id){if(!global.confirm('Clôturer cet exercice après contrôle de toutes les écritures ?'))return;try{await api().rpc('close_accounting_fiscal_year',{target_fiscal_year_id:id});ui.accountingCache=null;notify('Exercice contrôlé et clôturé.','success');renderAccountingSettings(state(),true);}catch(error){fail(error);}}
 async function saveAccounting(){try{const s=state(),settingsNode=document.querySelector('[data-settings="true"]'),invalid=document.querySelector('.ops-accounting-form [data-field]:invalid'),tasks=[];if(invalid){invalid.reportValidity();return;}if(settingsNode){const payload={company_id:s.companyId};settingsNode.querySelectorAll('[data-field]').forEach(input=>payload[input.dataset.field]=input.type==='checkbox'?input.checked:input.type==='number'?(input.value===''?null:Number(input.value)):input.value);tasks.push(api().request('/rest/v1/accounting_settings?on_conflict=company_id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(payload)}));}for(const row of document.querySelectorAll('.ops-config-table tr[data-table]')){const payload={};row.querySelectorAll('[data-field]').forEach(input=>payload[input.dataset.field]=input.type==='checkbox'?input.checked:input.type==='number'?(input.value===''?null:Number(input.value)):input.value||null);for(const key of ['account_code','financial_account_code','account_extension'])if(payload[key])payload[key]=String(payload[key]).trim().toUpperCase();if(!Object.keys(payload).length)continue;if(row.dataset.id)tasks.push(api().update(row.dataset.table,row.dataset.id,payload));else if(row.dataset.table==='accounting_account_mappings')tasks.push(api().insert('accounting_account_mappings',{company_id:s.companyId,direction:row.dataset.direction,scope_type:row.dataset.scopeType,scope_value:row.dataset.scopeValue,active:true,...payload}));else if(row.dataset.table==='accounting_payment_method_mappings')tasks.push(api().insert('accounting_payment_method_mappings',{company_id:s.companyId,payment_method:row.dataset.paymentMethod,...payload}));}await Promise.all(tasks);ui.accountingCache=null;notify('Paramétrage comptable enregistré.','success');renderAccountingSettings(s,true);}catch(error){fail(error);}}
 function addAccounting(kind){const year=String(new Date().getFullYear()),forms={fiscal:`${field('Nom de l’exercice','name',year,'text','required')}${field('Date de début','starts_on',`${year}-01-01`,'date','required')}${field('Date de fin','ends_on',`${year}-12-31`,'date','required')}`,journal:`${field('Code du journal','code','OD','text','required maxlength="10"')}${field('Libellé','label','Opérations diverses','text','required')}${select('Type','journal_type',[['sales','Ventes'],['purchases','Achats'],['bank','Banque'],['cash','Caisse'],['adjustment','Opérations diverses']],'adjustment')}`,purchase:`${select('Portée','scope_type',[['global','Global'],['item_type','Type d’élément'],['category','Catégorie'],['item','Article']],'global')}${field('Valeur','scope_value','*','text','required')}${field('Numéro de compte','account_code','607000','text','required')}`,vat:`${field('Taux de TVA (%)','tax_rate','20','number','required min="0" max="100" step="0.001"')}${field('Compte TVA sur achats','purchase_account','445661')}${field('Compte TVA sur ventes','sales_account','445713')}${field('Compte d’attente','suspense_account','445800')}${field('Extension du compte de vente','sale_account_extension','002')}`,financial:`${field('Nom du compte','name','BANQUE PRINCIPALE','text','required')}${field('N° de compte comptable','account_code','512100','text','required')}${select('Type de compte','account_type',[['bank','Banque'],['cash','Caisse'],['in_transit','Valeurs à l’encaissement'],['other','Autre']],'bank')}`};if(!forms[kind])return;modal(kind==='fiscal'?'Nouvel exercice':kind==='journal'?'Nouveau journal':kind==='vat'?'Nouveau taux de TVA':kind==='financial'?'Nouveau compte financier':'Nouvelle règle d’achat',`<form id="ops-accounting-create" class="ops-form" onsubmit="event.preventDefault();PilozOps.saveAccountingCreate('${kind}')">${forms[kind]}<div class="ops-modal-actions">${button('Annuler','PilozOps.closeModal()','btn-o')}<button type="submit" class="btn btn-p">Ajouter</button></div></form>`);}
 async function saveAccountingCreate(kind){const form=document.getElementById('ops-accounting-create');if(!form?.reportValidity())return;const s=state(),raw=Object.fromEntries(new FormData(form));try{if(kind==='fiscal')await api().insert('accounting_fiscal_years',{company_id:s.companyId,name:raw.name,starts_on:raw.starts_on,ends_on:raw.ends_on,status:'open'});else if(kind==='journal')await api().insert('accounting_journals',{company_id:s.companyId,code:String(raw.code).trim().toUpperCase(),label:String(raw.label).trim(),journal_type:raw.journal_type,active:true});else if(kind==='purchase')await api().insert('accounting_account_mappings',{company_id:s.companyId,direction:'purchase',scope_type:raw.scope_type,scope_value:raw.scope_value||'*',account_code:raw.account_code,active:true});else if(kind==='vat')await api().insert('accounting_vat_mappings',{company_id:s.companyId,tax_rate:Number(raw.tax_rate),purchase_account:raw.purchase_account||null,sales_account:raw.sales_account||null,suspense_account:raw.suspense_account||null,sale_account_extension:raw.sale_account_extension||null,purchase_account_extension:raw.sale_account_extension||null,active:true});else if(kind==='financial')await api().insert('accounting_financial_accounts',{company_id:s.companyId,name:raw.name,account_type:raw.account_type,account_code:raw.account_code,active:true});closeModal();ui.accountingCache=null;notify('Élément ajouté.','success');renderAccountingSettings(s,true);}catch(error){fail(error);}}
 async function controlAccounting(){try{const report=unwrap(await api().rpc('validate_accounting_configuration',{target_company_id:state().companyId}));modal('Contrôle du paramétrage',`<div class="ops-preview-summary">${status(report.ok?'Paramétrage exploitable':'Erreurs bloquantes',report.ok?'success':'danger')}</div>${[['Bloquant',report.blocking,'danger'],['Avertissement',report.warnings,'warning'],['Information',report.information,'info']].map(([title,items,tone])=>`<section class="ops-report-section"><h3>${esc(title)}</h3>${(items||[]).map(item=>`<p class="${tone}">${esc(item.message)}</p>`).join('')||'<p>Aucun.</p>'}</section>`).join('')}<div class="ops-modal-actions">${button('Fermer','PilozOps.closeModal()','btn-p')}</div>`,true);}catch(error){fail(error);}}

 async function renderSettingsDashboard(s){loading('Paramètres','État de votre entreprise, de vos services et de vos obligations.');try{const [connections,adminContext]=await Promise.all([api().query('external_connections',`select=id,status&company_id=eq.${s.companyId}`),api().rpc('platform_admin_context',{}).catch(()=>null)]);if(!['settings','settings/overview'].includes(path()))return;const company=s.data.settings?.[0]||{},configured=Boolean(company.legal_name&&company.siret),cards=[['settings/company','⌂','Mon entreprise','Identité, coordonnées, adresses et informations légales.',configured?'Configuré':'À compléter',configured?'success':'warning'],['settings/sales','€','Ventes & Documents','Numérotation, conditions et documents commerciaux.','Configuré','success'],['settings/company/bank','▣','Banque et règlements','Coordonnées bancaires et moyens de paiement.',company.iban?'Configuré':'À compléter',company.iban?'success':'warning'],['settings/users','♙','Équipe et accès','Membres, rôles et droits.','Gérer','info'],['settings/extensions','◉','Extensions','Agendas et messageries connectés.',`${connections.filter(row=>row.status==='connected').length} service(s) connecté(s)`,connections.some(row=>row.status==='error')?'danger':'info'],['settings/data','↯','Notifications','Préférences, activités et données.','À compléter','warning'],['settings/security','◇','Sécurité','Méthodes de connexion et protection du compte.','Configuré','success'],['settings/subscription','◆','Abonnement et utilisation','Offre, limites et facturation Piloz.','Voir l’offre','info'],['settings/templates','✎','Modèles de documents','Modèles, logos, couleurs, colonnes, pieds de page et CGV.','Configurer','info']];if(adminContext)cards.push(['settings/compliance','✓','Conformité','Contrôles fiscaux, RGPD et sécurité.','Contrôler','info'],['settings/about-compliance','i','À propos de Piloz','Version et périmètre fonctionnel.','Informations','muted']);document.getElementById('main').innerHTML=header('Paramètres','Retrouvez tous les réglages de votre entreprise et leur état actuel.')+`<div class="ops-settings-dashboard">${cards.map(([route,icon,title,description,label,tone])=>`<button onclick="PilozApp.go('${route}')"><span class="icon">${esc(icon)}</span><span class="copy"><b>${esc(title)}</b><small>${esc(description)}</small></span>${status(label,tone)}<span class="chevron">›</span></button>`).join('')}</div>`;}catch(error){fail(error);baseRender('settings',s);}}

 async function currentAuthUser(){const runtime=global.PilozRuntime,session=runtime?.session;if(!runtime?.config?.url||!runtime?.config?.key||!session?.access_token)return null;const response=await fetch(runtime.config.url.replace(/\/$/,'')+'/auth/v1/user',{headers:{apikey:runtime.config.key,Authorization:'Bearer '+session.access_token}});return response.ok?response.json():null;}
 async function renderSecurity(s){loading('Sécurité','Méthodes de connexion et protection de votre compte.');try{const user=await currentAuthUser();if(path()!=='settings/security')return;const identities=user?.identities||[],providers=new Map(identities.map(identity=>[identity.provider,identity])),emailIdentity=providers.get('email'),google=providers.get('google'),microsoft=providers.get('azure'),methodCount=[emailIdentity,google,microsoft].filter(Boolean).length,connection=(label,provider,identity)=>`<article class="ops-login-method"><span class="ops-extension-logo ${provider}">${providerLogo(provider)}</span><div><b>${esc(label)}</b><small>${identity?`Connecté · ${esc(identity.identity_data?.email||user?.email||'')}`:'Non connecté'}</small></div>${identity?(methodCount>1?button('Délier',`PilozOps.unlinkIdentity('${identity.id}')`,'btn-o'):status('Méthode requise','warning')):button('Lier',`PilozOps.linkIdentity('${provider}')`,'btn-p')}</article>`;document.getElementById('main').innerHTML=header('Méthodes de connexion','Piloz empêche de supprimer la dernière méthode permettant d’accéder au compte.')+`<section class="phase1-card"><div class="ops-account-summary"><div><small>Adresse principale</small><strong>${esc(user?.email||global.PilozRuntime?.session?.email||'—')}</strong></div><div><small>Dernière connexion</small><strong>${datetime(user?.last_sign_in_at)}</strong></div></div><div class="ops-login-methods">${connection('Adresse e-mail','email',emailIdentity)}${connection('Google','google',google)}${connection('Microsoft','azure',microsoft)}</div></section><aside class="ops-info-callout"><strong>Protection du compte</strong><span>Le rattachement et le retrait d’une identité sont traités directement par Supabase Auth. Les mots de passe et jetons de fournisseur ne sont jamais accessibles à Piloz.</span></aside>`;}catch(error){fail(error);baseRender.call(modern,'settings',s);}}
 async function linkIdentity(provider){try{const runtime=global.PilozRuntime,params=new URLSearchParams({provider,redirect_to:location.origin+location.pathname+'#settings/security'});if(provider==='azure')params.set('scopes','openid email profile');const response=await fetch(runtime.config.url.replace(/\/$/,'')+'/auth/v1/user/identities/authorize?'+params,{headers:{apikey:runtime.config.key,Authorization:'Bearer '+runtime.session.access_token}}),result=await response.json().catch(()=>({}));if(!response.ok||!result.url)throw new Error(result.msg||result.message||'Liaison indisponible.');location.assign(result.url);}catch(error){fail(error);}}
 async function unlinkIdentity(identityId){if(!global.confirm('Délier cette méthode de connexion ?'))return;try{const runtime=global.PilozRuntime,response=await fetch(runtime.config.url.replace(/\/$/,'')+'/auth/v1/user/identities/'+encodeURIComponent(identityId),{method:'DELETE',headers:{apikey:runtime.config.key,Authorization:'Bearer '+runtime.session.access_token}}),result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.msg||result.message||'La méthode n’a pas pu être déliée.');notify('Méthode de connexion déliée.','success');renderSecurity(state());}catch(error){fail(error);}}

 function renderRoute(route,s){const current=path();if(route==='settings'&&['settings','settings/overview'].includes(current)){renderSettingsDashboard(s);return true;}if(route==='settings'&&current==='settings/extensions'){renderExtensions(s);return true;}if(route==='settings'&&current==='settings/sales-terms'){renderSalesTerms(s);return true;}if(route==='settings'&&current==='settings/security'){renderSecurity(s);return true;}if(route==='accounting-payments'){renderPayments(s);return true;}if(route==='accounting-exports'){renderExports(s);return true;}if(route==='accounting-vat-cash'){renderVatCash(s);return true;}if(route==='accounting-fiscal-archives'){renderFiscalArchives(s);return true;}if(route==='accounting-settings'){renderAccountingSettings(s);return true;}return baseRender.call(modern,route,s);}
 modern.renderRoute=renderRoute;
 async function refreshDocumentVatRates(){const s=state();if(!s?.companyId)return;s.data.vatRates=await api().query('vat_rates',`select=*&company_id=eq.${s.companyId}&active=eq.true&order=rate.asc`);}
 async function saveAccountingAndSync(){await saveAccounting();if(ui.accountingTab==='vat')await refreshDocumentVatRates();}
 async function saveAccountingCreateAndSync(kind){await saveAccountingCreate(kind);if(kind==='vat')await refreshDocumentVatRates();}
